                    }
                }
                match self.argument(name) {
                    Some(Value::Int(n)) => Some(*n),
                    _ => None,
                }
            }
            Expr::UnaryOp { op, operand } if op == "-" => {
                self.integer(operand, depth + 1, last)?.checked_neg()
            }
            _ => None,
        }
    }
